-- All SELECTs are read-only. Time windows are UTC Unix epoch ranges.
-- Monthly exact-time reference availability and target/candidate RH agreement.
SELECT CASE WHEN a.`dateTime` >= 1640995200 AND a.`dateTime` < 1643673600 THEN 1 WHEN a.`dateTime` >= 1643673600 AND a.`dateTime` < 1646092800 THEN 2 WHEN a.`dateTime` >= 1646092800 AND a.`dateTime` < 1648771200 THEN 3 WHEN a.`dateTime` >= 1648771200 AND a.`dateTime` < 1651363200 THEN 4 WHEN a.`dateTime` >= 1651363200 AND a.`dateTime` < 1654041600 THEN 5 WHEN a.`dateTime` >= 1654041600 AND a.`dateTime` < 1656633600 THEN 6 WHEN a.`dateTime` >= 1656633600 AND a.`dateTime` < 1659312000 THEN 7 WHEN a.`dateTime` >= 1659312000 AND a.`dateTime` < 1661990400 THEN 8 WHEN a.`dateTime` >= 1661990400 AND a.`dateTime` < 1664582400 THEN 9 WHEN a.`dateTime` >= 1664582400 AND a.`dateTime` < 1667260800 THEN 10 WHEN a.`dateTime` >= 1667260800 AND a.`dateTime` < 1669852800 THEN 11 WHEN a.`dateTime` >= 1669852800 AND a.`dateTime` < 1672531200 THEN 12 END AS month_utc, COUNT(*) AS archive_rows, SUM(a.`outHumidity` IS NULL) AS target_RH_null, SUM(a.`outHumidity` IS NOT NULL) AS target_RH_nonnull, SUM(o.`observed_at_utc` IS NOT NULL) AS exact_LuhaMet_timestamps, SUM(o.`relative_humidity_pct` IS NOT NULL) AS exact_LuhaMet_RH_values, SUM(a.`outHumidity` IS NOT NULL AND o.`relative_humidity_pct` IS NOT NULL) AS comparable_RH_pairs, AVG(a.`outHumidity`-o.`relative_humidity_pct`) AS target_minus_LuhaMet_bias_pct, AVG(ABS(a.`outHumidity`-o.`relative_humidity_pct`)) AS RH_MAE_pct, SQRT(AVG(POW(a.`outHumidity`-o.`relative_humidity_pct`,2))) AS RH_RMSE_pct FROM `loucka_reconstruction`.`archive` a LEFT JOIN `loucka_reconstruction`.`reference_observations` o ON o.`station_id`='luhamet_sehradice' AND o.`observed_at_utc`=a.`dateTime` WHERE a.`dateTime` >= 1640995200 AND a.`dateTime` < 1672531200 GROUP BY month_utc ORDER BY month_utc;

-- Daily target/reference exact-time availability; epoch division maps to UTC day.
SELECT FLOOR(a.`dateTime`/86400) AS utc_day_epoch, COUNT(*) AS archive_rows, SUM(a.`outHumidity` IS NOT NULL) AS target_RH_nonnull, SUM(o.`observed_at_utc` IS NOT NULL) AS exact_LuhaMet_timestamps, SUM(o.`relative_humidity_pct` IS NOT NULL) AS exact_LuhaMet_RH_values, SUM(a.`outHumidity` IS NOT NULL AND o.`relative_humidity_pct` IS NOT NULL) AS comparable_RH_pairs, AVG(a.`outHumidity`-o.`relative_humidity_pct`) AS target_minus_LuhaMet_bias_pct, AVG(ABS(a.`outHumidity`-o.`relative_humidity_pct`)) AS RH_MAE_pct, SQRT(AVG(POW(a.`outHumidity`-o.`relative_humidity_pct`,2))) AS RH_RMSE_pct FROM `loucka_reconstruction`.`archive` a LEFT JOIN `loucka_reconstruction`.`reference_observations` o ON o.`station_id`='luhamet_sehradice' AND o.`observed_at_utc`=a.`dateTime` WHERE a.`dateTime` >= 1640995200 AND a.`dateTime` < 1672531200 GROUP BY utc_day_epoch ORDER BY utc_day_epoch;

-- 2022 current archive RH-null history reconciliation.
SELECT COUNT(*) AS target_rows, SUM(a.`outHumidity` IS NULL) AS current_RH_null_rows, SUM(a.`outHumidity` IS NULL AND EXISTS(SELECT 1 FROM `loucka_reconstruction`.`reconstruction_changes` h WHERE h.`target_time`=a.`dateTime` AND h.`variable`='outHumidity')) AS null_rows_with_any_RH_history, SUM(a.`outHumidity` IS NULL AND EXISTS(SELECT 1 FROM `loucka_reconstruction`.`reconstruction_changes` h WHERE h.`target_time`=a.`dateTime` AND h.`variable`='outHumidity' AND h.`state`='applied')) AS null_rows_with_applied_RH_history, SUM(a.`outHumidity` IS NULL AND NOT EXISTS(SELECT 1 FROM `loucka_reconstruction`.`reconstruction_changes` h WHERE h.`target_time`=a.`dateTime` AND h.`variable`='outHumidity')) AS null_rows_without_RH_history, SUM(a.`outHumidity` IS NOT NULL AND EXISTS(SELECT 1 FROM `loucka_reconstruction`.`reconstruction_changes` h WHERE h.`target_time`=a.`dateTime` AND h.`variable`='outHumidity')) AS nonnull_rows_with_RH_history FROM `loucka_reconstruction`.`archive` a WHERE a.`dateTime` >= 1640995200 AND a.`dateTime` < 1672531200;

-- February detail: all 8,058 current RH-null rows have no RH history event.
SELECT COUNT(*) AS rows_n, SUM(a.`outHumidity` IS NULL) AS rh_null, SUM(a.`outHumidity` IS NULL AND EXISTS(SELECT 1 FROM `loucka_reconstruction`.`reconstruction_changes` h WHERE h.`target_time`=a.`dateTime` AND h.`variable`='outHumidity')) AS null_with_any_history, SUM(a.`outHumidity` IS NULL AND EXISTS(SELECT 1 FROM `loucka_reconstruction`.`reconstruction_changes` h WHERE h.`target_time`=a.`dateTime` AND h.`variable`='outHumidity' AND h.`state`='applied')) AS null_with_applied_history, SUM(a.`outHumidity` IS NULL AND NOT EXISTS(SELECT 1 FROM `loucka_reconstruction`.`reconstruction_changes` h WHERE h.`target_time`=a.`dateTime` AND h.`variable`='outHumidity')) AS null_without_history FROM `loucka_reconstruction`.`archive` a WHERE a.`dateTime` >= 1643673600 AND a.`dateTime` < 1646092800;

-- February exact-reference value ranges and matched temperature context; not an RH transfer validation.
SELECT COUNT(*) AS target_rows, SUM(a.`outHumidity` IS NULL) AS target_RH_null_rows, COUNT(o.`relative_humidity_pct`) AS exact_LuhaMet_RH_values, MIN(o.`relative_humidity_pct`) AS LuhaMet_RH_min_pct, MAX(o.`relative_humidity_pct`) AS LuhaMet_RH_max_pct, AVG(o.`relative_humidity_pct`) AS LuhaMet_RH_mean_pct, SUM(o.`relative_humidity_pct`<0 OR o.`relative_humidity_pct`>100) AS RH_outside_0_100, SUM(a.`outTemp` IS NOT NULL AND o.`temperature_c` IS NOT NULL) AS paired_temperature_values, AVG(a.`outTemp`-o.`temperature_c`) AS target_minus_LuhaMet_temp_bias_C, AVG(ABS(a.`outTemp`-o.`temperature_c`)) AS paired_temperature_MAE_C, SQRT(AVG(POW(a.`outTemp`-o.`temperature_c`,2))) AS paired_temperature_RMSE_C, MIN(a.`outTemp`-o.`temperature_c`) AS paired_temperature_min_diff_C, MAX(a.`outTemp`-o.`temperature_c`) AS paired_temperature_max_diff_C FROM `loucka_reconstruction`.`archive` a LEFT JOIN `loucka_reconstruction`.`reference_observations` o ON o.`station_id`='luhamet_sehradice' AND o.`observed_at_utc`=a.`dateTime` WHERE a.`dateTime`>=1643673600 AND a.`dateTime`<1646092800;
